package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.contraptions.*;
import com.simibubi.create.content.contraptions.bearing.*;
import com.simibubi.create.content.contraptions.glue.SuperGlueEntity;
import com.simibubi.create.content.contraptions.render.ContraptionEntityRenderer;
import com.simibubi.create.content.kinetics.base.KineticBlockEntity;
import com.simibubi.create.content.kinetics.deployer.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import java.util.function.Predicate;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.BarrelBlockEntity;
import net.minecraft.world.phys.*;

/** Real moving USE/PUNCH, hand swap, native arm animation and unfinished-punch entity unload. */
final class MovingDeployerRenderingTest {
    private static final BlockPos P=new BlockPos(3951,5,5),B=P.below();
    private static final Vec3 ACTIVE=new Vec3(.5,.5,-1.5);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        verifyDirectionalTransforms(context);
        var server=world.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 3951.5 9 11.5");context.waitFor(client->Math.abs(client.player.getX()-3951.5)<.1&&client.level.isLoaded(P.east()),400);
        server.runCommand("fill 3945 3 -1 3960 3 13 minecraft:smooth_quartz");server.runCommand("setblock 3951 4 5 create:mechanical_bearing[facing=up]");server.runCommand("setblock 3951 5 5 create:deployer[facing=north]");server.runCommand("setblock 3952 5 5 minecraft:barrel[facing=north]");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var deployer=(DeployerBlockEntity)level.getBlockEntity(P);deployer.owner=level.getServer().getPlayerList().getPlayers().getFirst().getUUID();var filter=new ItemStack(AllItems.FILTER);filter.set(AllDataComponents.FILTER_ITEMS,net.minecraft.world.item.component.ItemContainerContents.fromItems(List.of(new ItemStack(Items.STONE),new ItemStack(Items.WOODEN_PICKAXE))));deployer.setFilter(filter);var barrel=(BarrelBlockEntity)level.getBlockEntity(P.east());barrel.setItem(0,new ItemStack(Items.STONE,5));barrel.setItem(4,new ItemStack(Items.DIAMOND,7));((MechanicalBearingBlockEntity)level.getBlockEntity(B)).setMovementMode(IControlContraption.RotationMode.ROTATE_NEVER_PLACE);level.addFreshEntity(new SuperGlueEntity(level,SuperGlueEntity.span(P,P.east())));});
        server.runCommand("setblock 3951 3 5 create:creative_motor[facing=up]");var id=new AtomicReference<UUID>();waitServer(context,world,level->{var owner=((MechanicalBearingBlockEntity)level.getBlockEntity(B)).getMovedContraption();if(owner==null)return false;id.set(owner.getUUID());return count(owner,Items.STONE)==0&&placed(level)==5;},400,"Moving deployer failed actual placement from shared storage");
        pause(world);context.waitTicks(8);context.waitFor(client->find(client.level,id.get()) instanceof ControlledContraptionEntity owner&&owner.getContraption()!=null,300);world.getConnection().waitForChunksRender();look(context,Vec3.atCenterOf(P));
        var useMesh=context.computeOnClient(client->{var state=renderState(client,id.get());if(state.hand.mesh.size()==0||state.pole.mesh.size()==0||state.shaft.mesh.size()==0||state.punching)throw new AssertionError("Native moving USE arm extraction incomplete");return state.hand.mesh;});screenshot(context,world,"create-vulkan-moving-deployer-placed-from-storage");
        approach(context,world);server.runCommand("item replace entity @p weapon.mainhand with create:wrench");context.waitFor(client->client.player.getMainHandItem().is(AllItems.WRENCH),150);use(context);context.waitFor(client->DeployerMovementBehaviour.getMode(actor((ControlledContraptionEntity)find(client.level,id.get())))==DeployerBlockEntity.Mode.PUNCH,200);context.runOnClient(client->{var state=renderState(client,id.get());if(!state.punching||state.hand.mesh==useMesh)throw new AssertionError("Actual wrench input did not change native moving hand pose");});screenshot(context,world,"create-vulkan-moving-deployer-native-mode-switch");
        server.runCommand("item replace entity @p weapon.mainhand with minecraft:wooden_pickaxe");context.waitFor(client->client.player.getMainHandItem().is(Items.WOODEN_PICKAXE),150);use(context);context.waitFor(client->client.player.getMainHandItem().isEmpty()&&DeployerMovementBehaviour.getHeldItem(actor((ControlledContraptionEntity)find(client.level,id.get()))).is(Items.WOODEN_PICKAXE),200);screenshot(context,world,"create-vulkan-moving-deployer-supplied-hand");
        var target=new AtomicReference<BlockPos>();server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var owner=(ControlledContraptionEntity)level.getEntity(id.get());for(var pos:BlockPos.betweenClosed(P.offset(-3,0,-3),P.offset(3,0,3)))if(level.getBlockState(pos).is(Blocks.STONE))level.setBlockAndUpdate(pos,Blocks.AIR.defaultBlockState());
            var previous=BlockPos.containing(owner.toGlobalVector(ACTIVE,1));for(int tick=1;tick<30;tick++){var point=StructureTransform.rotate(ACTIVE.subtract(.5,.5,.5),owner.getAngle(1)+tick*4.8f,Direction.Axis.Y).add(.5,.5,.5).add(owner.position());var next=BlockPos.containing(point);if(!next.equals(previous)){target.set(next);break;}}if(target.get()==null)throw new AssertionError("Fixture has no upcoming actor grid position");level.setBlockAndUpdate(target.get(),Blocks.STONE.defaultBlockState());((KineticBlockEntity)level.getBlockEntity(B.below())).setGeneratedSpeed(16);
        });
        waitServer(context,world,level->{var owner=(ControlledContraptionEntity)level.getEntity(id.get());return owner.isStalled()&&actor(owner).data.getFloatOr("BreakingProgress",0)>0;},300,"Actual moving PUNCH did not hold the bearing");context.waitFor(client->((ControlledContraptionEntity)find(client.level,id.get())).isStalled(),200);look(context,Vec3.atCenterOf(target.get()));
        float min=context.computeOnClient(client->renderState(client,id.get()).offset),max=min;for(int i=0;i<2;i++){context.waitTicks(3);float value=context.computeOnClient(client->renderState(client,id.get()).offset);min=Math.min(min,value);max=Math.max(max,value);}if(max-min<.03)throw new AssertionError("Stalled native arm is not animating");screenshot(context,world,"create-vulkan-moving-deployer-unfinished-punch");
        var oldAngle=new AtomicReference<Float>();var oldProgress=new AtomicReference<Float>();server.runOnServer(ignored->{var owner=(ControlledContraptionEntity)world.getConnection().getServerLevel().getEntity(id.get());oldAngle.set(owner.getAngle(1));oldProgress.set(actor(owner).data.getFloatOr("BreakingProgress",0));});
        server.runCommand("gamemode spectator @p");server.runCommand("tp @p 5000 10 5000");waitServer(context,world,level->level.getEntity(id.get())==null&&level.getChunkSource().getChunkNow(P.getX()>>4,0)==null&&level.getChunkSource().getChunkNow(P.east().getX()>>4,0)==null,800,"Moving fake player retained contraption chunks");
        server.runCommand("tp @p 3951.5 9 11.5");waitServer(context,world,level->level.getEntity(id.get()) instanceof ControlledContraptionEntity,500,"Unfinished deployer owner did not return");server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var owner=(ControlledContraptionEntity)level.getEntity(id.get());var ctx=actor(owner);if(!owner.isStalled()||Math.abs(owner.getAngle(1)-oldAngle.get())>.001||ctx.data.getFloatOr("BreakingProgress",0)<oldProgress.get()||!level.getBlockState(target.get()).is(Blocks.STONE))throw new AssertionError("Actual unload lost incomplete punch/pose: "+ctx.data);if(!DeployerMovementBehaviour.getHeldItem(ctx).is(Items.WOODEN_PICKAXE))throw new AssertionError("Actual unload lost supplied hand");});
        context.waitFor(client->find(client.level,id.get()) instanceof ControlledContraptionEntity owner&&owner.getContraption()!=null&&owner.isStalled(),300);look(context,Vec3.atCenterOf(target.get()));screenshot(context,world,"create-vulkan-moving-deployer-unfinished-punch-return");
        waitServer(context,world,level->{var owner=(ControlledContraptionEntity)level.getEntity(id.get());return level.getBlockState(target.get()).isAir()&&!owner.isStalled()&&count(owner,Items.COBBLESTONE)==1;},500,"Restored moving hand did not finish native mining");pause(world);context.waitTicks(8);approach(context,world);server.runCommand("item replace entity @p weapon.mainhand with minecraft:air");context.waitFor(client->client.player.getMainHandItem().isEmpty(),150);use(context);context.waitFor(client->client.player.getMainHandItem().is(Items.WOODEN_PICKAXE)&&client.player.getMainHandItem().getDamageValue()==1,200);screenshot(context,world,"create-vulkan-moving-deployer-retrieved-used-tool");use(context);context.waitFor(client->client.player.getMainHandItem().isEmpty()&&DeployerMovementBehaviour.getHeldItem(actor((ControlledContraptionEntity)find(client.level,id.get()))).getDamageValue()==1,200);
        var mesh=context.computeOnClient(client->renderState(client,id.get()).hand.mesh);var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone(),500);reload.join();context.waitTicks(3);context.runOnClient(client->{var state=renderState(client,id.get());if(state.hand.mesh==mesh||!state.punching)throw new AssertionError("Native deployer mode/geometry did not survive reload");});screenshot(context,world,"create-vulkan-moving-deployer-after-reload");
        var barrelPos=new AtomicReference<BlockPos>();server.runOnServer(ignored->{var owner=(ControlledContraptionEntity)world.getConnection().getServerLevel().getEntity(id.get());barrelPos.set(new StructureTransform(P,0,owner.getAngle(1),0).apply(new BlockPos(1,0,0)));});look(context,Vec3.atCenterOf(B));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(B),150);use(context);context.waitFor(client->find(client.level,id.get())==null,200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var deployer=(DeployerBlockEntity)level.getBlockEntity(P);if(!deployer.getHeldItem().is(Items.WOODEN_PICKAXE)||deployer.getHeldItem().getDamageValue()!=1||deployer.getMode()!=DeployerBlockEntity.Mode.PUNCH)throw new AssertionError("World deployer did not restore live hand and mode");var barrel=(BarrelBlockEntity)level.getBlockEntity(barrelPos.get());int diamonds=0,cobble=0;for(int i=0;i<barrel.getContainerSize();i++){var stack=barrel.getItem(i);if(stack.is(Items.DIAMOND))diamonds+=stack.getCount();if(stack.is(Items.COBBLESTONE))cobble+=stack.getCount();}if(diamonds!=7||cobble!=1)throw new AssertionError("World inventory lost/duplicated moving loot: "+diamonds+"/"+cobble);});look(context,Vec3.atCenterOf(P));screenshot(context,world,"create-vulkan-moving-deployer-world-restoration");server.runCommand("gamemode spectator @p");
    }
    private static void verifyDirectionalTransforms(ClientGameTestContext context){context.runOnClient(client->{
        for(var facing:Direction.values()){
            var state=new DeployerRenderer.State();state.facing=facing;state.offset=.375f;state.punching=true;
            var component=new com.mojang.blaze3d.vertex.PoseStack();component.translate(facing.getStepX()*state.offset,facing.getStepY()*state.offset,facing.getStepZ()*state.offset);DeployerRenderer.transformComponent(component,state,false);
            var tip=component.last().pose().transformPosition(new org.joml.Vector3f(.5f,.5f,1.25f));var expected=new Vec3(.5,.5,.5).add(facing.getUnitVec3().scale(state.offset+.75));
            if(new Vec3(tip.x,tip.y,tip.z).distanceTo(expected)>1e-5)throw new AssertionError("Native hand points against its block facing: "+facing);
            var item=new com.mojang.blaze3d.vertex.PoseStack();DeployerRenderer.transformHeldItem(item,state);var grip=item.last().pose().transformPosition(new org.joml.Vector3f());double distance=new Vec3(grip.x-.5,grip.y-.5,grip.z-.5).dot(facing.getUnitVec3());
            if(Math.abs(distance-state.offset-.75)>1e-5)throw new AssertionError("Native held-item grip is detached from hand: "+facing+"/"+distance);
        }
    });}
    private static com.simibubi.create.content.contraptions.behaviour.MovementContext actor(ControlledContraptionEntity owner){return owner.getContraption().getActorAt(BlockPos.ZERO).right;}
    private static DeployerRenderer.State renderState(net.minecraft.client.Minecraft client,UUID id){var owner=(ControlledContraptionEntity)find(client.level,id);var renderer=(ContraptionEntityRenderer)client.getEntityRenderDispatcher().getRenderer(owner);var state=renderer.createRenderState(owner,.5f);if(state.actors.size()!=1||state.blockEntities.stream().anyMatch(be->be.pos().equals(BlockPos.ZERO)))throw new AssertionError("Missing or duplicated native moving hand");return ((DeployerActorRenderer.State)state.actors.getFirst().state()).state();}
    private static int placed(ServerLevel level){int count=0;for(var pos:BlockPos.betweenClosed(P.offset(-3,0,-3),P.offset(3,0,3)))if(level.getBlockState(pos).is(Blocks.STONE))count++;return count;}
    private static long count(ControlledContraptionEntity owner,Item item){long total=0;for(var view:owner.getContraption().getStorage().getAllItems())if(view.getResource().isOf(item))total+=view.getAmount();return total;}
    private static net.minecraft.world.entity.Entity find(net.minecraft.client.multiplayer.ClientLevel level,UUID id){if(level==null)return null;for(var entity:level.entitiesForRendering())if(entity.getUUID().equals(id))return entity;return null;}
    private static void pause(TestSingleplayerContext world){world.getServer().runOnServer(ignored->((KineticBlockEntity)world.getConnection().getServerLevel().getBlockEntity(B.below())).setGeneratedSpeed(0));}
    private static void approach(ClientGameTestContext context,TestSingleplayerContext world){world.getServer().runCommand("tp @p 3951.5 4 9.5");world.getServer().runCommand("gamemode survival @p");context.waitFor(client->!client.player.isSpectator()&&Math.abs(client.player.getZ()-9.5)<.1,200);look(context,Vec3.atCenterOf(P));context.waitTicks(5);}
    private static void use(ClientGameTestContext context){context.waitTicks(6);context.getInput().pressKey(options->options.keyUse);}
    private static void waitServer(ClientGameTestContext context,TestSingleplayerContext world,Predicate<ServerLevel> predicate,int ticks,String message){var ready=new AtomicBoolean();for(int i=0;i<ticks&&!ready.get();i++){world.getServer().runOnServer(ignored->ready.set(predicate.test(world.getConnection().getServerLevel())));if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError(message);}
    private static void screenshot(ClientGameTestContext context,TestSingleplayerContext world,String name){
        NativeScreenshotReadiness.await(context,world);
        context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot(name);
    }
    private static void look(ClientGameTestContext context,Vec3 target){var angle=context.computeOnClient(client->{var d=target.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-d.x,d.z)),(float)-Math.toDegrees(Math.atan2(d.y,Math.hypot(d.x,d.z))));});context.getInput().lookAt(angle.x,angle.y);}
}
